(function(){async function n(n,i){const r=i.textContent;i.disabled=!0;i.innerHTML='<span class="spinner-border spinner-border-sm me-1"><\/span>Добавление...';try{const f=await fetch("/Catalog/AddToCart",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"id="+encodeURIComponent(n)});if(!f.ok)throw new Error("HTTP "+f.status);const u=await f.json();if(u.success){const n=document.getElementById("cartBadge");n&&(n.textContent=u.cartCount);t("Товар «"+u.productName+"» добавлен в корзину");i.innerHTML="✓ Добавлено";i.classList.remove("btn-primary");i.classList.add("btn-success");setTimeout(function(){i.textContent=r;i.classList.remove("btn-success");i.classList.add("btn-primary");i.disabled=!1},1e3)}else alert("Ошибка: "+u.message),i.textContent=r,i.disabled=!1}catch(u){console.error(u);i.textContent="Ошибка";i.disabled=!1;setTimeout(function(){i.textContent=r},2e3)}}function t(n){const t=document.getElementById("cartToast"),i=document.getElementById("cartToastText");if(t&&i){i.textContent=n;const r=new bootstrap.Toast(t,{delay:3e3});r.show()}}document.addEventListener("click",async function(t){const i=t.target.closest(".add-to-cart");if(i){const r=i.dataset.productId;await n(r,i)}})})();